  assign p_ecmp_count_l0_c[2] = mem_p_ecmp_count[2];
  logic [31:0] _key_3; assign _key_3 = mem_key_dstAddr[3];
  logic [31:0] _mask_3; assign _mask_3 = mem_pfx_mask_dstAddr[3];
  assign hit_l0_c[3] = mem_valid[3] && ((lkp_dstAddr & _mask_3) == (_key_3 & _mask_3));
